<template><div class="transform-grid"><template v-for="(v,i) in transform.xyz" :key="`p${i}`"><label>{{['X','Y','Z'][i]}}<el-input-number :model-value="v" :controls="false" disabled /></label></template><template v-for="(v,i) in transform.rpy" :key="`r${i}`"><label>{{['R','P','Y'][i]}}<el-input-number :model-value="v" :controls="false" disabled /></label></template></div></template>
<script setup lang="ts">import {computed} from 'vue'; import {useEditorStore} from '@/stores/editor'; import type {JointNode} from '@/types/scene'; const store=useEditorStore(); const transform=computed(()=>store.selectedType==='joint'?(store.selected as JointNode).origin:{xyz:[0,0,0],rpy:[0,0,0]})</script>
